import{_ as o,l as n,o as e,c as l,v as t,p as E,x as i,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"承诺装置","description":"","frontmatter":{"title":"承诺装置","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/commitment-devices.md","filePath":"econ/commitment-devices.md","lastUpdated":1789023840000}'),c={name:"econ/commitment-devices.md"};function m(h,a,A,B,_,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="承诺装置" tabindex="-1">承诺装置 <a class="header-anchor" href="#承诺装置" aria-label="Permalink to &quot;承诺装置&quot;">​</a></h1><div class="epigraph"><p>若未来的自己会改计划，有价值的不是更多选择，而是现在把某些选择关掉。</p><footer>—— Strotz, Myopia and Inconsistency in Dynamic Utility Maximization, RES 1955–56；Laibson, QJE 1997；对照 Thaler and Shefrin, AER 1981</footer></div><p><a href="/econ/hyperbolic-present-bias">上一课</a>给出准双曲与老练自我。本课缺口是：老练知道会偏，于是需求<strong>承诺</strong>——非流动性、默认缴存、合约罚则——把未来菜单缩小。不重写 \\(\\beta\\)–\\(\\delta\\)，只问装置如何进入预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数贴现下，更多选择弱优于更少（在无摩擦菜单上）。准双曲下这句话失败：未来菜单里若含「立刻吃掉储蓄」，老练的长期自我宁愿今天就看不见这个选项。缺口因此不是再定义偏好，而是承认<strong>约束可以是被需求的</strong>。这与显示偏好课的「选择揭示排序」不矛盾：被关掉的选项从未进入当期菜单，谈不上揭示。</p><p>也不要把承诺写成限价簿上的撤单限制。这里没有队列；装置是家庭资产负债表与合约条款。</p><p><span class="marginnote">幼稚自我不买承诺：他们以为未来会执行。观测到的承诺需求是老练程度的证据，不是贴现率本身的测量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Strotz 的策略是事先限制未来可行集。Thaler 与 Shefrin（1981）的计划者–执行者：长期自我选约束，短期自我在约束内花钱。Laibson 的金蛋：非流动资产在下一期才能变现，现时自我无法把它变成即期消费，于是均衡持有金蛋，哪怕其回报并不高。Ashraf、Karlan 与 Yin（2006）在田间提供不可提前支取的储蓄账户，需求来自意识到现时偏差的人。</p><p>承诺可以是市场的（定期存款、住房首付），也可以是制度的（养老金默认、强制年金）。本课先钉「缩小菜单有正价值」，具体生命周期与年金谜后课再接。</p>',10)),(e(),E(p,null,{default:i(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PB%5B%22%E7%8E%B0%E6%97%B6%E5%81%8F%E5%B7%AE%3A%20%E6%9C%AA%E6%9D%A5%E4%BC%9A%E6%94%B9%E8%AE%A1%E5%88%92%22%5D%20--%3E%20DEM%5B%22%E8%80%81%E7%BB%83%E9%9C%80%E6%B1%82%3A%20%E5%85%B3%E6%8E%89%E9%80%89%E6%8B%A9%22%5D%0A%20%20DEM%20--%3E%20ILL%5B%22%E9%9D%9E%E6%B5%81%E5%8A%A8%E8%B5%84%E4%BA%A7%20%2F%20%E9%87%91%E8%9B%8B%22%5D%0A%20%20DEM%20--%3E%20DEF%5B%22%E9%BB%98%E8%AE%A4%E4%B8%8E%E5%90%88%E7%BA%A6%E7%BD%9A%E5%88%99%22%5D%0A%20%20ILL%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%3A%20%E6%8C%81%E6%9C%89%E4%BD%8E%E6%B5%81%E5%8A%A8%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是改变未来自我的可行集，从而改变子博弈完美均衡。提高提款成本、拉长锁定期、把边际储蓄设成默认，都是把 \\(c_{t+1}\\) 的上界或价格改掉。计划者并不需要改变 \\(\\beta\\)，只需要改变预算。这与宏观里「规则而非权变」同构但对象不同：那里绑的是政府，这里绑的是下一期的自己。</p><p>代价是流动性损失与冲击到来时的再融资成本。承诺过度会在收入风险下后悔——预防性储蓄与流动性约束是后课，本课只标出权衡：现时偏差要锁，风险要留一扇门。</p><p>与宏观政策课的承诺不是同一合同：Kydland–Prescott 绑的是政府，面对的是私人预期；这里绑的是下一期的自己，面对的是同一人的 \\(\\beta\\)。工具可以长得像（规则、锁定期），对象必须分开写。默认缴存是后课素养与助推的接口，本课只要求：老练自我愿意为缩小菜单付正价格。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有非流动性都是承诺。交易成本、信息不对称、住房的消费服务，都会产生不流动，不必有双曲。识别承诺需求要看：人是否愿意为「不能提前取」付正价格。本课不估计该价格，不把助推课提前写完。</p><p>后课默认：生命周期与储蓄制度可以当承诺读，但先要有一个时间一致或准双曲的计划，才知道锁的是哪一种自我。</p><p>承诺需求识别的是老练程度：愿意为不能提前取付正价格。幼稚自我会拒绝同一合同。</p><p>后课把养老金默认、住房首付和年金加载都当成候选装置，先要分清锁的是流动性还是自我。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>现时偏差下，关掉未来选择可以是需求，不是缺陷。</li><li>金蛋、锁定期、默认缴存，改的是可行集，不是 \\(\\beta\\)。</li><li>幼稚不买承诺；观测到的装置是老练的线索。</li><li>装置改可行集，不改贴现参数本身。</li><li>与政策承诺同构，对象是下一期的自己。</li><li>出处：Strotz, <em>RES</em> 1955–56；Thaler and Shefrin, <em>AER</em> 1981；Laibson, <em>QJE</em> 1997；Ashraf, Karlan and Yin, <em>QJE</em> 2006。</li></ul>',11))])}const D=o(c,[["render",m]]);export{u as __pageData,D as default};
